N = 2025

def color(x, y):
    # Assuming W2 proposed the 4-coloring C(x, y) = (x + 2y) mod 4
    return (x + 2 * y) % 4

def check_sufficiency():
    for x in range(N):
        for y in range(N):
            c_xy = color(x, y)

            # Check 8 neighboring points (dx, dy in {-1, 0, 1}, excluding (0, 0))
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue

                    # Toroidal wrap-around
                    a = (x + dx) % N
                    b = (y + dy) % N

                    c_ab = color(a, b)

                    if c_xy == c_ab:
                        print(f"Conflict found at ({x}, {y}) and neighbor ({a}, {b}). Colors are both {c_xy}.")
                        return False
    return True

print("Starting 4-coloring sufficiency test for N=2025...")
result = check_sufficiency()
if result:
    print("Test successful: The 4-coloring proposed by W2 appears sufficient for the toroidal lattice with N=2025.")
else:
    print("Test failed: The 4-coloring is insufficient.")
